import React, { useState } from 'react';
import QuestionDisplay from './QuestionDisplay';
import AnswerOptions from './AnswerOptions';
import ScoreDisplay from './ScoreDisplay';
import useQuizLogic from '../hooks/useQuizLogic';
import quizData from '../utils/quizData';

const App = () => {
    const { currentQuestionIndex, userAnswers, score, handleAnswerSelection, nextQuestion, resetQuiz } = useQuizLogic(quizData);

    return (
        <div className="quiz-app">
            {currentQuestionIndex < quizData.length ? (
                <>
                    <QuestionDisplay question={quizData[currentQuestionIndex]} />
                    <AnswerOptions 
                        options={quizData[currentQuestionIndex].answers} 
                        onAnswerSelected={handleAnswerSelection} 
                    />
                    <button onClick={nextQuestion}>Next</button>
                </>
            ) : (
                <ScoreDisplay score={score} totalQuestions={quizData.length} onReset={resetQuiz} />
            )}
        </div>
    );
};

export default App;
